"""Apply the bounded, already source-verified Analyst A follow-up; record exact deltas."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
REV = '2026-11-02-zzzzzzz-c-liver'
FILES = ['chcca/data/pathway.json', 'chcca/data/critique.json', 'hilar/data/pathway.json', 'hilar/data/critique.json', 'tools/consensus_source/roadmap_chcca.json', 'tools/consensus_source/roadmap_hilar.json']
raw = {f: (ROOT / f).read_text() for f in FILES}
data = {f: json.loads(s) for f, s in raw.items()}
patches, register = [], []
SOURCES = {
 'lee': {'pmid': '30552477', 'findings': ['C-0067', 'C-0068', 'C-0076'], 'locator': 'Primary PDF pp2–5 and Table 3, PDF p7 / printed p2414; Denominator_Phenotype_Version_Checks.md'},
 'auer': {'pmid': '37174120', 'findings': ['B:S582505efe5', 'B:Sb8a44024c0', 'B:S2d0ba34ff5'], 'locator': 'Primary abstract and conclusion, printed pp1 and 13–14; Analyst_B/B16/R7/37174120.md and B16_A_Continuation.md'},
 'lrt': {'pmid': '34283065', 'findings': ['C-0102–0109', 'B:S5b098ff484', 'B:S9dfefe4224', 'B:S5daae33b88', 'B:Scf83e1ea7c'], 'locator': 'Primary PDF pp9–11, CHC section and Table 2; CCA_Consensus_and_LRT_Targeted_Checks.md. Underlying Y90 reports not fully re-read; no new survival/response figure adopted.'},
 'lvd': {'pmid': '40478744', 'findings': ['C-0214', 'C-0215', 'C-0299'], 'locator': 'Primary PDF pp21–22 and Table 2, PDF p76, Recommendations 23–25; CCA_Consensus_and_LRT_Targeted_Checks.md'},
 'ceus': {'pmid': '33362387', 'findings': ['C-0118–0121'], 'locator': 'Primary PDF pp3–5 and 8, Methods, diagnostic rule, Results and Table 5; CCA_Consensus_and_LRT_Targeted_Checks.md'},
 'milan_tx': {'pmid': '40478744', 'findings': ['C-0214', 'C-0215', 'C-0299', 'accepted carry-through: distinct LT recommendations'], 'locator': 'Primary PDF pp30–32 and Table 2, PDF p80, Recommendations 59–64; CCA_Consensus_and_LRT_Targeted_Checks.md'},
 'nlrb': {'pmid': None, 'findings': ['accepted carry-through: cHCC-CCA-D8 qualifying scope'], 'locator': 'Previously reconciled OPTN NLRB Adult MELD Exceptions for Transplant Oncology, Intrahepatic Cholangiocarcinoma section; current roadmap Gate 5 and Gate 8 flagnote; D8 rationale'}
}

def get(f, pointer):
    obj = data[f]
    for k in pointer.strip('/').split('/'):
        obj = obj[int(k)] if isinstance(obj, list) else obj[k]
    return obj

def change(f, pointer, new, group, why):
    old = get(f, pointer)
    assert isinstance(old, str) and old != new, (f, pointer)
    before, after = json.dumps(old, ensure_ascii=False), json.dumps(new, ensure_ascii=False)
    assert raw[f].count(before) == 1, (f, pointer, raw[f].count(before))
    raw[f] = raw[f].replace(before, after, 1)
    obj = data[f]
    keys = pointer.strip('/').split('/')
    for k in keys[:-1]: obj = obj[int(k)] if isinstance(obj, list) else obj[k]
    obj[int(keys[-1]) if isinstance(obj, list) else keys[-1]] = new
    patches.append({'file': f, 'old': before, 'new': after, 'why': why, 'source': SOURCES[group]})
    register.append({'file': f, 'pointer': pointer, 'old': old, 'new': new, 'group': group, 'source': SOURCES[group], 'why': why})

P, C = 'chcca/data/pathway.json', 'chcca/data/critique.json'
change(P, '/gates/0/standard/1/avoid', "Do not read LR-M as 'this is cHCC-CCA', and do not read its absence as exclusion. Requiring three or more LR-M features raises accuracy to 80.8% but drops sensitivity to 54.5%, so that rule misses nearly half of these tumours. Targetoid appearance was present in 25 of 33 cHCC-CCA (75.8%) and 23 of 66 matched HCC controls (34.8%), giving 65.2% specificity. This surgically confirmed, propensity-matched sample does not establish clinic-wide predictive values or an imaging-only diagnosis.", 'lee', 'Correct HCC-control positivity versus specificity and remove the inference built on the inverted denominator.')
change(P, '/gates/0/alt/0/opts/0/when', 'Gadoxetate MRI assesses rim arterial phase hyperenhancement, peripheral washout, delayed central enhancement and targetoid diffusion restriction. Targetoid appearance occurred in 25 of 33 cHCC-CCA (75.8%) and 23 of 66 matched HCC controls (34.8%), giving 65.2% specificity; it raises suspicion but does not establish mixed histology.', 'lee', 'Use the verified targetoid numerator, denominator and diagnostic limitation.')
change(P, '/quickref/3/rows/1/1', 'Present in 25/33 cHCC-CCA (75.8%) and 23/66 matched HCC controls (34.8%); specificity 65.2%', 'lee', 'Propagate the corrected diagnostic denominator into the quick reference.')
change(P, '/honest/11/why', get(P, '/honest/11/why').replace('targetoid appearance alone was present in 75.8% of cHCC-CCA and 65.2% of matched HCC.', 'targetoid appearance was present in 25/33 cHCC-CCA (75.8%) and 23/66 matched HCC (34.8%), giving 65.2% specificity.'), 'lee', 'Propagate targetoid positivity/specificity distinction into uncertainty text.')
change(C, '/30552477/bottom_line', 'In 33 cHCC-CCA and 66 matched HCC controls, targetoid appearance occurred in 25/33 (75.8%) and 23/66 (34.8%), respectively, giving 65.2% specificity. A three-feature LR-M rule had 80.8% accuracy but only 54.5% sensitivity. These selected, surgically confirmed groups do not establish clinic-wide predictive values or an imaging-only diagnosis.', 'lee', 'Give the correct source-specific diagnostic result and retain the selected-cohort limitation.')
Q = 'tools/consensus_source/roadmap_chcca.json'
change(Q, '/questions/2/positions/2/position', get(Q, '/questions/2/positions/2/position') + ' Targetoid appearance alone occurred in 25/33 mixed tumours (75.8%) and 23/66 matched HCC controls (34.8%), giving 65.2% specificity; these are separate results from the any-LR-M-feature rule.', 'lee', 'Keep the consensus source aligned while distinguishing the two diagnostic rules.')

change(P, '/gates/8/crit/3', 'Explicit acknowledgement of small retrospective disease-specific cohorts, with no established comparative curative benefit or validated transplant-selection rule', 'lrt', 'Acknowledge dedicated cHCC-CCA evidence without claiming an established treatment or listing rule.')
change(P, '/gates/8/standard/0/t', 'Record the disease-specific retrospective evidence and the extrapolation behind each liver-directed treatment.', 'lrt', 'Remove the false all-modalities/all-extrapolation and uniformly lower-response premise.')
change(P, '/gates/8/standard/0/pref', 'Every case. Renzulli reviews dedicated retrospective cHCC-CCA cohorts treated with TACE, TARE and hepatic arterial infusion, including a TACE analysis by enhancement pattern. Its reduced-responsiveness discussion concerns TACE and percutaneous ethanol injection; it does not establish that every liver-directed modality is less effective than in HCC. Enhancement pattern and histological predominance are different observations, neither a validated universal selection rule. Separate adjuvant data in 306 resected tumours found improved early recurrence-free survival only in the HCC-dominant group (53.3% against 32.3% at two years, p=0.028), not in balanced (p=0.276) or CCA-dominant (p=0.433) patients.', 'lrt', 'Separate dedicated retrospective cohorts, modality-specific rationale and adjuvant component-defined data.')
change(P, '/gates/8/standard/0/avoid', 'Do not quote an HCC response rate, a BCLC algorithm or an iCCA radioembolisation series as a cHCC-CCA treatment effect. The dedicated mixed-tumour series are small, retrospective and heterogeneous in treatment, response criteria and survival time origin. The review contains inconsistent outcome labels across its narrative and table, so primary reports must control any numerical estimate. These data do not establish comparative curative benefit or validate transplant selection.', 'lrt', 'Retain evidence limits while removing the claim that dedicated mixed cohorts and enhancement analyses do not exist.')
change(P, '/gates/8/standard/0/note', 'The Standard/grade D label applies to documenting the evidence and uncertainty for every proposed treatment. It does not designate one liver-directed modality as an established standard for cHCC-CCA.', 'lrt', 'Clarify the existing documentation label without activating a treatment policy or changing grades.')
change(P, '/gates/8/alt/0/opts/0/when', get(P, '/gates/8/alt/0/opts/0/when').replace('The most used modality and the one with the most supporting data, though all of it is retrospective and the benefit is confined.', 'Dedicated retrospective TACE series include unresectable and recurrent cHCC-CCA; enhancement-pattern associations do not establish a causal treatment benefit. Keep the following adjuvant cohorts separate from those treatment settings.'), 'lrt', 'Do not reduce all TACE evidence to adjuvant treatment or claim an untested modality ranking.')
change(P, '/gates/8/alt/0/opts/0/avoid', get(P, '/gates/8/alt/0/opts/0/avoid').replace('Do not use it for a hypovascular, CCA-predominant tumour and expect a response — the quantitative imaging work in this disease shows that a large hypovascular component is what distinguishes cHCC-CCA from HCC in the first place, and the one cohort that stratified adjuvant TACE by component found no signal outside the HCC-dominant group.', 'Hypovascularity may limit embolic responsiveness, but enhancement is not interchangeable with histological predominance and does not prove that an individual tumour cannot respond. The separate component-stratified adjuvant cohort found no signal outside the HCC-dominant group.'), 'lrt', 'Remove an absolute no-response claim and distinguish imaging enhancement from histological component.')
change(P, '/gates/8/alt/0/opts/1/when', 'Small retrospective cHCC-CCA radioembolisation series are reported in the disease-specific literature summarized by Renzulli. Auer supplies an interventional iCCA review with an outlook for mixed tumours, not a separate mixed-tumour efficacy estimate.', 'lrt', 'Replace the false no-cHCC-CCA-data claim and distinguish the two reviews.')
change(P, '/gates/8/alt/0/opts/1/avoid', 'Small uncontrolled series do not establish superiority to TACE, systemic therapy or surgery, nor validate transplant selection. Response denominators, criteria and survival time origins differ; do not combine their estimates. Treat use as an individualized multidisciplinary or protocol/registry decision.', 'lrt', 'Retain restrictive interpretation while acknowledging the dedicated series.')
change(P, '/gates/8/alt/0/order', 'The order is for discussion, not a comparative efficacy ranking. Dedicated retrospective experience exists for TACE and TARE; evidence for ablation remains limited and includes extrapolation. The reviewed series do not establish which modality improves survival most or which response qualifies a patient for transplant.', 'lrt', 'Remove the false absent-series claim without introducing a new clinical ranking.')
change(P, '/honest/17/t', 'Liver-directed therapy has small retrospective cHCC-CCA series, including TACE and TARE, but no established comparative curative benefit or validated transplant-selection rule.', 'lrt', 'Correct the repeated assertion of no dedicated evidence.')
change(P, '/honest/17/why', 'Renzulli includes dedicated mixed-histology cohorts and an enhancement-pattern analysis. Auer mainly reviews interventional iCCA therapy and presents an outlook for cHCC-CCA. Tumour enhancement and histological predominance should not be conflated or treated as validated universal predictors. Small cohorts, heterogeneous treatments, response criteria and survival time origins prevent a pooled efficacy claim; numerical outcomes require checking the primary reports because the review has inconsistent labels. Separate adjuvant post-operative TACE data in 95 resected patients reported HR 0.2 for overall survival (p=0.005, no confidence interval reported), from a retrospective hepatitis-B-endemic cohort with substantial selection concerns. That association does not establish efficacy in unresectable disease or on a transplant pathway.', 'lrt', 'Preserve the adjuvant result and caveats while correcting the broader evidence scope.')
change(C, '/34283065/critique/0', 'The review has a dedicated cHCC-CCA section and Table 2 with retrospective TACE, TARE and hepatic arterial infusion experience. Cohort totals are not interchangeable with treated denominators: the Fowler series contained 79 patients overall but only 18 receiving liver-directed therapy.', 'lrt', 'Correct the absent-dedicated-data claim and guard the cohort versus treatment denominator.')
change(C, '/34283065/critique/1', 'The review discusses enhancement-pattern associations after TACE. Its lower-responsiveness rationale concerns TACE and percutaneous ethanol injection, not proven inferiority of every modality to HCC. Enhancement pattern is not equivalent to histological predominance and is not a validated universal eligibility rule.', 'lrt', 'Remove the unsupported Kim 4-versus-16-month claim and the false absent-enhancement-analysis claim.')
change(C, '/34283065/critique/2', 'No pooled estimates are provided. Outcome labels and survival time origins conflict between parts of the narrative and Table 2; do not sum cohorts as an independent treated population or quote a response/survival figure without checking its primary report.', 'lrt', 'Retain the synthesis limitation and record the verified internal inconsistencies.')
change(C, '/34283065/critique/3', 'The small retrospective mixed-tumour series do not validate comparative curative efficacy, modern combination regimens or transplant selection.', 'lrt', 'Remove the unsupported assertion that combination regimens dominate cHCC-CCA practice.')
change(C, '/34283065/bottom_line', 'A narrative locoregional review with dedicated small retrospective cHCC-CCA TACE and TARE data and an enhancement-pattern analysis. It provides no pooled effect or validated transplant-selection rule; inconsistent outcome labels require primary-report checks before quoting numerical efficacy.', 'lrt', 'Summarize the actual source scope and limitations.')
change(C, '/37174120/critique/0', 'The principal subject is interventional iCCA therapy, followed by an outlook for cHCC-CCA. It provides no cHCC-CCA-specific comparative systemic-treatment result and does not establish a gemcitabine–platinum/checkpoint standard for mixed histology.', 'auer', 'Correct the systemic recommendation attribution to an interventional review.')
change(C, '/37174120/critique/1', 'No pooled cHCC-CCA response or survival estimate is supplied. Its interventional rationale may inform discussion, but numerical expected benefit must come from an applicable primary cohort with its limitations.', 'auer', 'Distinguish absent quantitative efficacy from a claim that the review cannot inform discussion.')
change(C, '/37174120/critique/2', 'Statements about locoregional downstaging and retrospective activity principally concern iCCA; they are not validated cHCC-CCA efficacy or transplant-selection estimates.', 'auer', 'Replace an obsolete extraction-status assertion with the source-specific clinical limitation verified by the later complete read.')

change(P, '/gates/0/alt/0/opts/1/avoid', 'Not for whole-liver assessment, surveillance or staging — NCCN does not recommend it for those. The 40.0% sensitivity, 89.9% specificity and AUC 0.649 describe a combined CEUS LI-RADS/AFP/CA 19-9 diagnostic rule, not CEUS alone. The authors modelled PPV as 1.6–39.6% across assumed disease prevalences; these are not predictive values measured in an unselected clinic. Separately, 25.7% of the 35 mixed tumours were assigned CEUS LR-5, showing that this imaging label can miss mixed histology.', 'ceus', 'Attribute diagnostic accuracy to the combined test and distinguish modelled PPV from observed clinic performance.')
change(P, '/quickref/3/rows/5/0', 'Combined CEUS LI-RADS plus AFP/CA 19-9 rule', 'ceus', 'Name the complete tested diagnostic method.')
change(P, '/quickref/3/rows/5/1', '40.0% sensitive, 89.9% specific, AUC 0.649; modelled PPV 1.6–39.6% across assumed prevalences. Separately, CEUS assigned 74.3% of mixed tumours LR-M and 25.7% LR-5', 'ceus', 'Separate the combined-rule accuracy from CEUS category proportions.')
change(P, '/honest/11/why', get(P, '/honest/11/why').replace('On contrast-enhanced ultrasound the CEUS LI-RADS criteria for cHCC-CCA were 40.0% sensitive with an AUC of 0.649, and the authors honestly recalculated the positive predictive value at real prevalence as 1.6% to 39.6%.', 'The combined CEUS LI-RADS/AFP/CA 19-9 rule was 40.0% sensitive and 89.9% specific, with AUC 0.649; its modelled positive predictive value was 1.6–39.6% across assumed disease prevalences. These are not CEUS-alone accuracy estimates or predictive values observed in an unselected clinic.'), 'ceus', 'Propagate the diagnostic-method and modelled-PPV distinction.')
change(C, '/33362387/critique/0', 'The 40.0% sensitivity and 89.9% specificity apply to a combined CEUS LI-RADS/AFP/CA 19-9 rule. The modelled PPV range of 1.6–39.6% depends on assumed prevalence; neither that range nor the enriched-cohort PPV is an observed unselected-clinic estimate.', 'ceus', 'Keep method, endpoint and prevalence denominator together.')
change(C, '/33362387/critique/1', 'The combined rule misses 60% of mixed tumours at 40.0% sensitivity and cannot exclude cHCC-CCA. The separate finding that 74.3% of mixed tumours were CEUS LR-M is a category proportion, not the combined rule’s sensitivity.', 'ceus', 'Correct the CEUS-alone interpretation and separate category proportion from diagnostic sensitivity.')
change(C, '/33362387/critique/2', 'The combined rule’s AUC of 0.649 indicates limited discrimination in this selected cohort; it requires prospective validation and cannot establish an imaging-only diagnosis.', 'ceus', 'Attach discrimination to the tested combined rule.')
change(C, '/33362387/n', '134 surgically confirmed lesions: 35 cHCC-CCA, 29 iCCA and 70 matched HCC controls', 'ceus', 'Use the verified comparator denominators and selected surgical population.')
change(C, '/33362387/bottom_line', 'A combined CEUS LI-RADS/AFP/CA 19-9 rule had 40.0% sensitivity, 89.9% specificity and AUC 0.649 in 35 cHCC-CCA, 29 iCCA and 70 matched HCC controls. The modelled PPV was 1.6–39.6% across assumed prevalences. These are not CEUS-alone accuracy estimates, and the selected surgical cohort does not establish clinic-wide predictive values.', 'ceus', 'Correct the source summary and retain prevalence and selection limitations.')

change(Q, '/questions/7/positions/1/position', 'The nonstandard NLRB guidance route concerns biopsy-proven, unresectable solitary mixed HCC-iCCA 3 cm or less in cirrhosis, after locoregional or systemic therapy. It requires six months from diagnosis or last treatment with the tumour remaining ≤3 cm, no new lesions and no extrahepatic disease. It does not reproduce the local CPG’s external-beam-radiation exclusion or its strict under-3-cm restriction on locoregional therapy alone.', 'nlrb', 'Carry the accepted qualifying scope into the previously overbroad consensus position.')
change(Q, '/questions/7/divergence', 'For the NLRB guidance population of a solitary tumour ≤3 cm in cirrhosis, the local CPG imposes a stricter under-3-cm restriction on locoregional-only bridging and excludes external-beam radiation. Small retrospective liver-directed series do not resolve those local transplant restrictions.', 'nlrb', 'State the narrow policy disagreement without suggesting unrestricted eligibility or absence of all mixed LRT data.')
change(Q, '/questions/7/proposal', 'The local rule stands until the group changes it: external-beam radiation before transplant remains Avoid under the local protocol, and the locoregional-only restriction remains an OPEN local choice. Plan treatment and the six-month stability assessment together, applying the full NLRB guidance criteria rather than stability alone.', 'nlrb', 'Preserve the unapproved policy choice and remove an unsupported claim that the local restriction is unnecessarily conservative.')
change(P, '/gates/8/standard/1/note', 'The local CPG permits TACE, radiofrequency ablation and Y-90 but excludes external-beam radiation, and permits locoregional therapy alone before transplant only for a solitary tumour under 3 cm. This remains an OPEN local rule. The NLRB guidance route is restricted to a solitary tumour ≤3 cm in cirrhosis with the other required criteria; the retrospective liver-directed series do not establish whether the local restrictions should be changed.', 'nlrb', 'Align the repeated local-policy comparison with the accepted full NLRB scope without activating a policy.')

P, C, Q = 'hilar/data/pathway.json', 'hilar/data/critique.json', 'tools/consensus_source/roadmap_hilar.json'
change(P, '/gates/3/alt/0/opts/0/when', 'Milan recommends portal vein embolisation as the initial hypertrophy technique (Recommendation 23: strong, level of evidence 3) when the anticipated remnant is inadequate. The remaining lobe needs intact arterial and portal inflow and effective biliary drainage.', 'lvd', 'State the source’s initial-technique recommendation and actual evidence level.')
change(P, '/gates/3/alt/0/opts/1/when', 'Milan Recommendation 24 supports considering upfront or additional liver venous deprivation when substantial augmentation is needed: future liver remnant <20–25%, altered liver parenchyma and/or right extended hepatectomy. The recommendation is strong, level of evidence 3.', 'lvd', 'Correct the after-PVE-only timing, indication scope and source evidence level.')
change(P, '/gates/3/alt/0/opts/1/pref', 'Expert-centre review for expected impaired regeneration or substantial augmentation needs. PVE remains the recommended initial technique; LVD need not be restricted to rescue after PVE failure.', 'lvd', 'Separate general PVE initial preference from the permitted upfront-LVD scenario.')
change(P, '/gates/3/alt/0/opts/1/avoid', 'LVD does not substitute for drainage of the remnant. Limited pCCA comparative data suggest better functional growth with similar morbidity, but do not establish a randomized survival advantage or a universal LVD-first policy.', 'lvd', 'Remove the false no-comparative-data claim and retain the small nonrandomized evidence limitation.')
change(P, '/gates/3/alt/0/order', 'PVE is Milan’s recommended initial technique; upfront or additional LVD may be considered for substantial augmentation. Both Recommendations 23 and 24 are strong, level of evidence 3. This is not a comparative survival ranking. Milan does not suggest ALPPS as the initial procedure; its recommendation is weak, level of evidence 5, and the registry mortality concern remains.', 'lvd', 'Replace the blanket level-4/strict-sequence assertion with the separate source recommendations.')
old = get(P, '/gates/4/avoid/1/note')
change(P, '/gates/4/avoid/1/note', old.replace('The Milan jury acknowledged benefit in node-negative patients independent of resectability; that is a consensus position resting on one benchmark study and mixed retrospective comparisons, and TRANSPHIL, the randomised trial meant to settle it, failed to recruit.', 'Milan Recommendation 59 supports transplant consideration for selected unresectable or PSC-associated pCCA above the cystic duct, ≤3.0 cm radial diameter and without nodal or distant metastases (strong, level 3), with staging and neoadjuvant therapy specified separately. Recommendation 64 only weakly supports consideration for resectable or questionably resectable pCCA when appropriate donor access exists (level 3). These are distinct consensus recommendations, not proof that transplantation is superior for every resectable patient; TRANSPHIL failed to recruit. The consensus ≤3.0 cm boundary does not replace the separate OPTN strict <3 cm mass criterion.'), 'milan_tx', 'Separate recommendations, disease setting and source strength while preserving the distinct OPTN boundary.')
change(C, '/40478744/bottom_line', 'The Milan jury-based consensus covers staging, drainage, liver augmentation, resection, systemic therapy, transplantation and outcomes; 84% of its 570 studies are observational and most surgical recommendations sit at level of evidence 4. Hypertrophy is a specific exception: PVE is the initial technique (Recommendation 23), and upfront or additional LVD may be considered for substantial augmentation (Recommendation 24), both strong, level 3, with limited nonrandomized pCCA comparative evidence. Transplant Recommendation 59 concerns selected unresectable or PSC-associated pCCA ≤3.0 cm without nodal or distant metastases (strong, level 3); Recommendation 64 only weakly supports consideration in resectable or questionably resectable disease with appropriate donor access (level 3). Benchmark and retrospective data do not establish universal superiority over resection, and TRANSPHIL failed to recruit. The consensus size boundary is separate from OPTN’s strict <3 cm mass criterion. Resectability criteria still need validation. Industry covered 55% of the conference’s costs, no individual author conflict statement is printed, and no voting record is reported.', 'milan_tx', 'Correct the flattened transplant stance and the LVD-specific evidence grade while retaining the source’s methodological caveats.')
change(Q, '/questions/0/positions/3/position', 'Recommendation 59 supports consideration for selected unresectable or PSC-associated pCCA ≤3.0 cm radial diameter without nodal or distant metastases (strong, level 3), with staging and neoadjuvant therapy specified separately. Recommendation 64 only weakly supports consideration in resectable or questionably resectable disease with appropriate donor access (level 3). Neither establishes universal superiority over resection; the consensus boundary does not replace OPTN’s strict <3 cm mass criterion.', 'milan_tx', 'Propagate distinct Milan recommendations into the consensus record.')
change(Q, '/questions/0/divergence', 'Milan distinguishes selected unresectable/PSC-associated disease from a weaker recommendation for resectable or questionably resectable disease; AASLD has its own PSC preference. Supporting transplant comparisons are retrospective and heavily selected, and TRANSPHIL failed to recruit. Opening a protocol remains an institutional decision under the applicable OPTN requirements.', 'milan_tx', 'Preserve governance status without flattening different source recommendations.')

manifest = {'id': REV, 'baseline': 'b3ef22b', 'note': 'Analyst A source-specific carry-through from accepted B/C reviews and prior verified reconciliations. Exact owned-file changes only; clinical grades and local activation remain unchanged. No new full-paper audit or automatic acceptance of external review claims.', 'sources': [], 'edits': [], 'files': patches}
manifest_path = ROOT / 'tools/clinical_revisions' / (REV + '.json')
assert not manifest_path.exists(), 'Already applied; use manifest replay rather than rerunning this one-shot helper.'
for f, s in raw.items():
    assert json.loads(s) == data[f]
    (ROOT / f).write_text(s)
manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n')
(ROOT / 'tools/audit_followup/c_liver_change_register.json').write_text(json.dumps({'baseline': 'b3ef22b', 'manifest': str(manifest_path.relative_to(ROOT)), 'changes': register}, ensure_ascii=False, indent=2) + '\n')
print(f'Applied {len(patches)} exact changes across {len(set(p["file"] for p in patches))} owned files.')
